  def ph_icon(name, size: 18)
    d = PHOSPHOR.fetch(name.to_s)
    content_tag(:svg, xmlns: "http://www.w3.org/2000/svg", viewBox: "0 0 256 256", width: size, height: size, fill: "currentColor", "aria-hidden": true, focusable: false) do
